import type { Knex } from 'knex';

/**
 * JGN package catalog import. Sourced from jgn-items.xlsx (sheet: 'package').
 * Generated by _tmp_xlsx/build_mapping_packages.py — regenerate rather than
 * editing by hand.
 *
 * Package codes: PKG-01 … PKG-10 (zero-padded source ItemPackageID; source
 * ID 9 is intentionally skipped in the workbook, so PKG-09 is not emitted).
 *
 * Per-line new_price is a proportional split of the package total by list
 * price; rounding drift lands on the highest-priced line so
 * SUM(new_price) == package_price to the cent (matches the invariant the
 * item-package service enforces at sync time).
 *
 * Runs via env vars so the same seed can target any tenant:
 *   JGN_TENANT_UUID=<uuid> \
 *     npx knex seed:run --specific 10_seed_jgn_packages.ts
 *
 * Also exported as seedJgnPackages(knex, opts) for direct calls.
 *
 * Idempotent — packages checked by (tenant_uuid, code); package items
 * checked by (item_package_uuid, test_item_uuid). Existing rows untouched.
 * Fails loudly if any referenced test code does not exist in the tenant's
 * test_items — better to abort than silently drop a package line.
 */

interface PackageLineSeed {
	test_code: string;
	current_price: number;
	new_price: number;
	display_order: number;
}

interface PackageSeed {
	code: string;
	name: string;
	package_price: number;
	items: PackageLineSeed[];
}

