export interface SeedJgnPackagesOptions {
	tenant_uuid: string;
	created_by?: string;
}

export interface SeedJgnPackagesResult {
	packages_inserted: number;
	packages_skipped: number;
	lines_inserted: number;
}

export async function seedJgnPackages(
	knex: Knex,
	opts: SeedJgnPackagesOptions,
): Promise<SeedJgnPackagesResult> {
	const { tenant_uuid } = opts;
	const created_by = opts.created_by ?? 'seed:10_seed_jgn_packages';
	let packages_inserted = 0;
	let packages_skipped = 0;
	let lines_inserted = 0;

	// Resolve every referenced test code up front so we fail before writing
	// anything on a bad reference.
	const allCodes = Array.from(
		new Set(PACKAGES.flatMap((p) => p.items.map((i) => i.test_code))),
	);
	const testRows: Array<{ uuid: string; code: string }> = await knex('test_items')
		.where({ tenant_uuid })
		.whereIn('code', allCodes)
		.select('uuid', 'code');
	const testUuidByCode = new Map(testRows.map((r) => [r.code, r.uuid]));
	const missing = allCodes.filter((c) => !testUuidByCode.has(c));
	if (missing.length) {
		throw new Error(
			`[seed 10] Cannot import packages — missing test_items in tenant ${tenant_uuid}: ${missing.join(', ')}`,
		);
	}

	for (const pkg of PACKAGES) {
		let row = await knex('item_packages')
			.where({ tenant_uuid, code: pkg.code })
			.first();
		if (row) {
			packages_skipped += 1;
		} else {
			const [inserted] = await knex('item_packages')
				.insert({
					tenant_uuid,
					code: pkg.code,
					name: pkg.name,
					package_price: pkg.package_price,
					status: 'active',
					created_by,
				})
				.returning('*');
			row = inserted;
			packages_inserted += 1;
		}

		for (const line of pkg.items) {
			const test_item_uuid = testUuidByCode.get(line.test_code)!;
			const exists = await knex('item_package_items')
				.where({ item_package_uuid: row.uuid, test_item_uuid })
				.first();
			if (exists) continue;
			await knex('item_package_items').insert({
				tenant_uuid,
				item_package_uuid: row.uuid,
				test_item_uuid,
				current_price: line.current_price,
				new_price: line.new_price,
				display_order: line.display_order,
				created_by,
			});
			lines_inserted += 1;
		}
	}

	return { packages_inserted, packages_skipped, lines_inserted };
}

export async function seed(knex: Knex): Promise<void> {
	const tenant_uuid = process.env.JGN_TENANT_UUID;
	if (!tenant_uuid) {
		// eslint-disable-next-line no-console
		console.warn(
			'[seed 10] Skipped — set JGN_TENANT_UUID env var, ' +
				'or import seedJgnPackages() and call it directly with your id.',
		);
		return;
	}
	const result = await seedJgnPackages(knex, { tenant_uuid });
	// eslint-disable-next-line no-console
	console.log(
		`[seed 10] Packages inserted=${result.packages_inserted} skipped=${result.packages_skipped}, ` +
			`lines inserted=${result.lines_inserted}`,
	);
}
